default.shell:
$mismatchCount = 0

$key = Get-Item -LiteralPath 'HKLM:\Software\Policies\Microsoft\Windows NT\Printers\RPC' -ErrorAction SilentlyContinue
$current = $null
if ($key) { $current = $key.GetValue('ForceKerberosForRpc', $null, 'DoNotExpandEnvironmentNames') }
if (-not ($current -is [int] -and [BitConverter]::ToUInt32([BitConverter]::GetBytes($current), 0) -eq [uint32]$ODV_force_kerberos_for_rpc)) {
    Write-Output 'Mismatch: HKLM:\Software\Policies\Microsoft\Windows NT\Printers\RPC [ForceKerberosForRpc]'
    $mismatchCount++
}

if ($mismatchCount -gt 0) { exit 1 }
exit 0

steps.shell:
$ErrorActionPreference = 'Stop'
trap { Write-Output $_.Exception.Message; exit 1 }

if (-not (Test-Path -LiteralPath 'HKLM:\Software\Policies\Microsoft\Windows NT\Printers\RPC')) {
    New-Item -Path 'HKLM:\Software\Policies\Microsoft\Windows NT\Printers\RPC' -Force | Out-Null
}
New-ItemProperty -LiteralPath 'HKLM:\Software\Policies\Microsoft\Windows NT\Printers\RPC' -Name 'ForceKerberosForRpc' -Value $ODV_force_kerberos_for_rpc -PropertyType DWord -Force | Out-Null
exit 0
